{"function": "Asking preference", "situation": "Asking a friend about their favorite food", "cue": "Ask your friend what food they like.", "text": "何が好き？", "english": "What do you like?", "speaker": "either", "reading": "なにがすき？", "romana": "nani ga suki"},
{"function": "Stating preference", "situation": "Answering a question about what you like", "cue": "Tell your friend that you like Japanese food.", "text": "日本食が好きだよ。", "english": "I like Japanese food.", "speaker": "either", "reading": "にほんしょくがすきだよ。", "romana": "nihonshoku ga suki da yo"},
{"function": "Asking about liking", "situation": "Asking if a friend likes something specific", "cue": "Ask your friend if they like that movie.", "text": "あれ、好き？", "english": "Do you like that?", "speaker": "either", "reading": "あれ、すき？", "romana": "are suki"},
{"function": "Confirming liking", "situation": "Confirming that you like something", "cue": "Tell your friend you really like it.", "text": "本当、好きだよ。", "english": "I really like it.", "speaker": "either", "reading": "ほんとう、すきだよ。", "romana": "hontou suki da yo"},
{"function": "Describing liking", "situation": "Describing something you like to a friend", "cue": "Tell your friend that this book is interesting/you like this book.", "text": "この本、好きだな。", "english": "I like this book.", "speaker": "either", "reading": "このほん、すきだな。", "romana": "kono hon suki da na"},
{"function": "Asking about preference", "situation": "Asking a friend about their preference between two things", "cue": "Ask your friend which one they like better.", "text": "どっちが好き？", "english": "Which one do you like?", "speaker": "either", "reading": "どっちがすき？", "romana": "docchi ga suki"}
]}

{"teachable": true, "reason": "", "candidates": [
{"function": "Getting attention", "situation": "Trying to get a shopkeeper's attention", "cue": "Get the shopkeeper's attention to ask about a price.", "text": "すみません、あれいくらですか。", "english": "Excuse me, how much is that?", "speaker": "either", "reading": "すみません、あれいくらですか。", "romaji": "sumimasen are ikura desu ka"},
{"function": "Apology", "situation": "Accidentally bumping into someone", "cue": "Apologise for bumping into your friend.", "text": "あ、すみません。", "english": "Oh, excuse me / sorry.", "speaker": "either", "reading": "あ、すみません。", "romaji": "a sumimasen"},
{"function": "Declining politely", "situation": "Declining an offer of more food", "cue": "Politely refuse more food.", "text": "いいえ、すみません。もうお腹いっぱいです。", "english": "No, thank you. I'm already full.", "speaker": "either", "reading": "いいえ、すみません。もうおなかはいっぱいです。", "romaji": "iie sumimasen mou onaka ippai desu"},
{"function": "Apology", "situation": "Realising you made a small mistake", "cue": "Apologise for a small mistake.", "text": "すみません、間違えました。", "english": "Sorry, I made a mistake.", "speaker": "either", "reading": "すみません、まちがえました。", "romaji": "sumimasen machigaemashita"},
{"function": "Getting attention", "situation": "Asking someone for directions", "cue": "Ask someone for the way to the station.", "text": "すみません、駅はどこですか。", "english": "Excuse me, where is the station?", "speaker": "either", "reading": "すみません、えきはどこですか。", "romaji": "sumimasen eki wa doko desu ka"},
{"function": "Apology", "situation": "Being slightly late", "cue": "Apologise for being a little late.", "text": "すみません、ちょっと遅れました。", "english": "Sorry, I'm a little late.", "speaker": "either", "reading": "すみません、ちょっとおくnamelyました。", "romaji": "sumimasen chotto okuremashita"}
]}

{"teachable": true, "reason": "", "candidates": [
{"function": "Asking amount", "situation": "Asking the price of something", "cue": "Ask how much something costs.", "text": "これいくらですか", "english": "How much is this?", "speaker": "either", "reading": "これいくらですか", "romaji": "kore ikura desu ka"},
{"function": "Stating possession", "situation": "Confirming you have money", "cue": "Confirm that you have money.", "text": "おかねあるよ", "english": "I have money.", "speaker": "either", "reading": "おかねあるよ", "romaji": "okane aru yo"},
{"function": "Offering to pay", "situation": "Offering to pay for a friend", "cue": "Offer to pay for your friend.", "text": "おかねだいじょうぶだよ", "english": "It's okay about the money (I'll pay).", "speaker": "either", "reading": "おかねだいじょうぶだよ", "romaji": "okane daijoubu da yo"},
{"function": "Asking about money", "situation": "Asking if a friend has money", "cue": "Ask your friend if they have money.", "text": "おかねある", "english": "Do you have money?", "speaker": "either", "reading": "おかねある", "romaji": "okane aru"},
{"function": "Describing cost", "situation": "Talking about expensive items", "cue": "Say that the book is expensive.", "text": "そのほんたかいね", "english": "That book is expensive, isn't it?", "speaker": "either", "reading": "そのほんたかいね", "romaji": "sono hon takai ne"},
{"function": "Asking about spending", "situation": "Asking a friend what they bought", "cue": "Ask your friend what they bought with their money.", "text": "なにかったの", "english": "What did you buy?", "speaker": "either", "reading": "なにかったの", "romaji": "nani katta no"}
]}
